import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"契约与请求","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/request.md","filePath":"frontend/request.md","lastUpdated":1794049926000}`),a={name:`frontend/request.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="契约与请求" tabindex="-1">契约与请求 <a class="header-anchor" href="#契约与请求" aria-label="Permalink to “契约与请求”">​</a></h1><p>本页说明前端的契约生成物、操作调用、请求头与错误处理，适用于前端开发者与修改后端契约的开发者。</p><p>前端没有手写的 API 层：一份 <code>openapi.json</code>、一个生成器、一个运行时客户端。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>后端操作登记 ──contracts export──&gt; contracts/openapi.json + realtime.json</span></span>
<span class="line"><span>                                            │  pnpm gen:contracts</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                         packages/contracts/{types,operations,permissions,enums,realtime}.ts</span></span>
<span class="line"><span>                                            │  import { users } from &#39;~/contracts&#39;</span></span>
<span class="line"><span>                                            ▼</span></span>
<span class="line"><span>                         packages/request：invoke → fetch → ApiError</span></span></code></pre></div><h2 id="生成物" tabindex="-1">生成物 <a class="header-anchor" href="#生成物" aria-label="Permalink to “生成物”">​</a></h2><p><code>scripts/gen-contracts.mjs</code> 读 <code>contracts/openapi.json</code> 与 <code>contracts/realtime.json</code>：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>types.ts</code></td><td><code>openapi-typescript</code> 生成的 <code>paths</code> / <code>components</code> / <code>operations</code> 类型；DataAnnotations 折进 Schema 的约束（<code>minLength</code>、<code>maximum</code> …）随之进入类型</td></tr><tr><td><code>operations.ts</code></td><td>路由表 <code>routes</code>（方法、模板、路由字段、查询串字段、成功码）、<code>RequestOf</code> / <code>ResponseOf</code> 类型与按资源分组的调用函数</td></tr><tr><td><code>permissions.ts</code></td><td>权限码字面量联合 <code>Permission</code>、操作 → 权限 / 策略映射 <code>operationPermission</code> / <code>operationPolicy</code>、权限定义表 <code>permissionDefinitions</code>（码与英文的显示名、说明；界面显示取 <code>permissions.list</code>）</td></tr><tr><td><code>enums.ts</code></td><td>字符串枚举的成员数组与类型（如 <code>UserStatus = [&#39;Active&#39;, &#39;Disabled&#39;, &#39;Locked&#39;]</code>）</td></tr><tr><td><code>realtime.ts</code></td><td>Hub 路径 <code>RealtimeHubs</code>、推送方法名 <code>RealtimeMethods</code>、客户端可调方法名 <code>RealtimeInvocations</code></td></tr></tbody></table><p><code>paging.ts</code> 是手写的：把 SchemaPage 的查询参数转成后端的 <code>PageRequest</code>、把分页结果转回 SchemaPage 读的形状，见 <a href="./schema-page#资源适配器">Schema 驱动页面</a>。</p><p>生成物不要手改。CI 先用后端重新导出 <code>contracts/*</code> 比对，再重新生成比对（<code>pnpm contracts:check</code>），任一漂移即失败。改契约的顺序：后端操作 → 导出 → 生成 → 改页面与测试 → 同一提交。</p><h2 id="调用" tabindex="-1">调用 <a class="header-anchor" href="#调用" aria-label="Permalink to “调用”">​</a></h2><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { users } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;~/contracts&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> page</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ page: { index: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, size: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, keyword: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;zhang&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id })</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ ids: [id] }) </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// BatchResult：{ succeeded, failed: [{ id, code, message }] }</span></span></code></pre></div><p>每个函数的签名是 <code>(request: RequestOf&lt;&#39;&lt;操作 ID&gt;&#39;&gt;, options?: CallOptions) =&gt; Promise&lt;ResponseOf&lt;&#39;&lt;操作 ID&gt;&#39;&gt;&gt;</code>，操作 ID <code>&lt;资源&gt;.&lt;动词&gt;</code> 的资源段换成驼峰作对象名（<code>export-tasks.submit</code> → <code>exportTasks.submit</code>）。没有请求参数的操作照样传 <code>{}</code>。</p><p><code>invoke</code> 按路由表拼请求：路由字段进路径；登记为查询串的字段，以及 <code>GET</code> / <code>DELETE</code> 的其余标量字段进查询串（数组按同名参数重复）；其余字段作为 JSON 请求体。路由由后端的 HTTP 约定决定，常见形态：</p><table tabindex="0"><thead><tr><th>动词</th><th>HTTP</th></tr></thead><tbody><tr><td><code>list</code>（带 <code>PageRequest</code>）</td><td><code>POST /api/&lt;资源&gt;:list</code></td></tr><tr><td><code>list</code>（不分页）</td><td><code>GET /api/&lt;资源&gt;</code></td></tr><tr><td><code>get</code></td><td><code>GET /api/&lt;资源&gt;/{id}</code></td></tr><tr><td><code>create</code></td><td><code>POST /api/&lt;资源&gt;</code>，成功码 201</td></tr><tr><td><code>update</code></td><td><code>PUT /api/&lt;资源&gt;/{id}</code></td></tr><tr><td><code>delete</code></td><td><code>DELETE /api/&lt;资源&gt;?ids=…</code></td></tr><tr><td>其他写动词</td><td><code>POST /api/&lt;资源&gt;:&lt;动词&gt;</code></td></tr></tbody></table><p>以 <code>operations.ts</code> 的 <code>routes</code> 为准，不手写路由。</p><p><code>CallOptions</code>：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><code>signal</code></td><td>取消</td></tr><tr><td><code>deadline</code></td><td>截止时间（<code>Date</code>），以 UTC ISO 8601 写进 <code>xihan-deadline</code></td></tr><tr><td><code>locale</code></td><td>覆盖本次调用的区域</td></tr><tr><td><code>headers</code></td><td>额外请求头</td></tr><tr><td><code>anonymous</code></td><td>匿名调用（登录、刷新、注册、找回密码）：不带令牌，未认证也不走刷新钩子</td></tr></tbody></table><h3 id="普通端点" tabindex="-1">普通端点 <a class="header-anchor" href="#普通端点" aria-label="Permalink to “普通端点”">​</a></h3><p>上传、下载这类普通端点不进 <code>operations.ts</code>，用 <code>~/request</code> 的：</p><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>uploadForm(path, form, { onProgress?, signal? })</code></td><td>multipart 上传：带令牌、区域与 <code>traceparent</code>，未认证时先刷新再重放一次，可报告进度</td></tr><tr><td><code>downloadEndpoint(path)</code></td><td>下载：同样带令牌并在未认证时重放一次，返回 <code>{ blob, fileName }</code>，再交给 <code>~/utils</code> 的 <code>downloadBlob</code></td></tr><tr><td><code>endpointUrl(path)</code></td><td>普通端点或后端签发的相对地址补上接口前缀</td></tr></tbody></table><p>文件的下载与预览优先换签名地址（<code>files.presign</code>），签名地址不带令牌也能取。</p><h2 id="请求头" tabindex="-1">请求头 <a class="header-anchor" href="#请求头" aria-label="Permalink to “请求头”">​</a></h2><table tabindex="0"><thead><tr><th>头</th><th>来源</th></tr></thead><tbody><tr><td><code>Authorization: Bearer</code></td><td><code>getToken()</code>，匿名调用不带</td></tr><tr><td><code>Accept-Language</code></td><td>当前区域（缺省 <code>en-US</code>）</td></tr><tr><td><code>traceparent</code></td><td>每个请求新生成（W3C）</td></tr><tr><td><code>xihan-deadline</code></td><td>传了 <code>deadline</code> 才有</td></tr></tbody></table><h2 id="错误" tabindex="-1">错误 <a class="header-anchor" href="#错误" aria-label="Permalink to “错误”">​</a></h2><p>失败统一抛 <code>ApiError</code>（由 Problem Details 解包），字段 <code>code</code>、<code>status</code>、<code>detail</code>、<code>traceId</code>、<code>errors?</code>、<code>details?</code>：</p><ul><li><code>detail</code> 已按 <code>Accept-Language</code> 本地化、可直接展示，<code>message</code> 与它相同，不带错误码；</li><li>分支只看 <code>code</code>（<code>&lt;前缀&gt;_&lt;KIND&gt;_&lt;NNN&gt;</code>，如 <code>ACCESS_DENIED_006</code>），<code>kind</code> 取中段（<code>VALIDATION</code>、<code>NOTFOUND</code>、<code>DENIED</code>…）；</li><li>响应没有 <code>code</code> 时按状态码补：401 → <code>SECURITY_DENIED_001</code>，404 → <code>PROTOCOLS_NOTFOUND_000</code>，其余 <code>KERNEL_UNEXPECTED_000</code>；</li><li>字段级 <code>errors</code> 是字段键 → 消息数组，<code>hasFieldErrors</code> / <code>fieldError(field)</code> 取用，页面用 <code>XhFieldRoot :invalid</code> + <code>XhFieldErrorText</code> 挂回对应字段；</li><li>批量结果的失败项带本地化的 <code>message</code>，<code>throwOnFailed(result)</code>（<code>~/request</code>）把不同的原因拼成一条报错抛出，不把部分失败当成功。</li></ul><p>运行时客户端按错误码触发钩子：</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>钩子</th><th>行为</th></tr></thead><tbody><tr><td><code>SECURITY_DENIED_001</code> / <code>SECURITY_DENIED_003</code></td><td><code>onUnauthenticated</code></td><td>用刷新令牌换一次（并发请求共用同一次刷新）并重放；刷新也失败即回登录页</td></tr><tr><td><code>IDENTITY_DENIED_001</code></td><td><code>onSessionInvalid</code></td><td>会话已吊销，清会话回登录页</td></tr><tr><td><code>IDENTITY_DENIED_002</code></td><td><code>onLocked</code></td><td>按 <code>details.reason</code> 拉起锁屏或强制改密表单</td></tr><tr><td><code>RUNTIME_UNAVAILABLE_003</code>、<code>KERNEL_UNAVAILABLE_001</code></td><td><code>onMaintenance</code></td><td>维护提示（10 秒内只提示一次）</td></tr></tbody></table><p>页面不重复实现这些处理。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p><code>main.ts</code> 在启动时调用 <code>configureRequest({ baseUrl, getToken, getLocale, hooks })</code>。<code>baseUrl</code> 取 <code>VITE_API_BASE_URL</code>，留空即同源；开发态经 Vite 代理到后端。</p><h2 id="时间与-id" tabindex="-1">时间与 ID <a class="header-anchor" href="#时间与-id" aria-label="Permalink to “时间与 ID”">​</a></h2><p>主键是 UUID 字符串；后端的 <code>long</code> 在报文里是数字（契约类型 <code>number</code>）。时间是 UTC 的 ISO 8601 字符串，前端用 <code>~/utils</code> 的 <code>formatDate</code> 按应用时区显示（见<a href="./i18n#时区">国际化与时区</a>）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./schema-page">Schema 驱动页面</a> · <a href="./../api-guide">接口对接指南</a> · <a href="./permission">权限与脱敏</a></li></ul>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};